// Generated by hb-performance (perf.py instrumentar); `instrumentar --actualizar` overwrites this file.
package {{PAQUETE}}

import android.os.SystemClock
import okhttp3.Headers
import okhttp3.Interceptor
import okhttp3.Response
import okio.Buffer
import okio.GzipSource
import okio.buffer
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.io.IOException
import java.util.Locale
import java.util.concurrent.atomic.AtomicInteger

// The full request and response of every call, only in the test run of hb-performance (perf.py capturar --prueba).
// perf.py creates <dir>/ACTIVA before that run and deletes it after, then pulls <dir>/NNNN-request.json and
// NNNN-response.json with adb. In the measured runs the file is not there: the interceptor checks it at most once per
// second and passes each call through without reading any body.
// Everything is written as is, unmasked: every header (Authorization and cookies included) and the whole bodies. The
// files only go to the investigation folder, which is outside git. A binary body goes to NNNN-<side>.bin.
// It is a network interceptor, so it sees the headers OkHttp adds (cookies, Accept-Encoding) and every redirect.
// "seccion" and "inicio_ns" (elapsedRealtimeNanos, the clock of the trace) link each file to its HTTP section.
class TestNetworkCapture(private val folder: () -> File?) : Interceptor {
    @Volatile private var active = false
    @Volatile private var checkedAt = 0L
    @Volatile private var dir: File? = null

    override fun intercept(chain: Interceptor.Chain): Response {
        if (!isActive()) return chain.proceed(chain.request())
        val request = chain.request()
        val id = String.format(Locale.ROOT, "%04d", COUNTER.incrementAndGet())
        val start = SystemClock.elapsedRealtimeNanos()
        val section = "HTTP " + HttpSectionName.endpoint(request)
        val body = request.body
        val sent = if (body == null || body.isDuplex() || body.isOneShot()) null else
            Buffer().also { body.writeTo(it) }.readByteArray()
        write(
            "$id-request.json",
            JSONObject().put("id", id).put("seccion", section).put("inicio_ns", start)
                .put("metodo", request.method).put("url", request.url.toString())
                .put("headers", headers(request.headers))
                .withBody(sent, body?.contentType()?.toString(), "$id-request.bin"),
        )
        val response = try {
            chain.proceed(request)
        } catch (error: IOException) {
            write(
                "$id-response.json",
                JSONObject().put("id", id).put("seccion", section).put("inicio_ns", start)
                    .put("fin_ns", SystemClock.elapsedRealtimeNanos()).put("error", error.toString()),
            )
            throw error
        }
        val raw = response.peekBody(Long.MAX_VALUE).bytes()
        val gzip = response.header("Content-Encoding").equals("gzip", ignoreCase = true)
        write(
            "$id-response.json",
            JSONObject().put("id", id).put("seccion", section).put("inicio_ns", start)
                .put("fin_ns", SystemClock.elapsedRealtimeNanos()).put("codigo", response.code)
                .put("mensaje", response.message).put("protocolo", response.protocol.toString())
                .put("headers", headers(response.headers)).put("bytes_red", raw.size).put("gzip", gzip)
                .withBody(if (gzip) unzip(raw) else raw, response.header("Content-Type"), "$id-response.bin"),
        )
        return response
    }

    private fun isActive(): Boolean {
        val now = SystemClock.elapsedRealtime()
        if (checkedAt == 0L || now - checkedAt >= CHECK_MS) {
            val current = dir ?: folder()?.let { File(it, DIR) }?.also { it.mkdirs(); dir = it }
            active = current != null && File(current, FLAG).exists()
            checkedAt = now
        }
        return active
    }

    private fun headers(headers: Headers): JSONArray {
        val out = JSONArray()
        for (index in 0 until headers.size) out.put(JSONArray().put(headers.name(index)).put(headers.value(index)))
        return out
    }

    private fun JSONObject.withBody(bytes: ByteArray?, type: String?, binary: String): JSONObject {
        put("cuerpo_tipo", type ?: JSONObject.NULL)
        if (bytes == null) return put("cuerpo", JSONObject.NULL)
        put("cuerpo_bytes", bytes.size)
        if (isText(type, bytes)) return put("cuerpo", String(bytes, Charsets.UTF_8))
        writeBytes(binary, bytes)
        return put("cuerpo", JSONObject.NULL).put("cuerpo_archivo", binary)
    }

    private fun isText(type: String?, bytes: ByteArray): Boolean {
        val lower = type?.lowercase(Locale.ROOT)
        if (lower != null) return TEXT_TYPES.any { lower.contains(it) }
        return bytes.none { it == 0.toByte() }
    }

    private fun unzip(raw: ByteArray): ByteArray = try {
        GzipSource(Buffer().write(raw)).buffer().readByteArray()
    } catch (error: IOException) {
        raw
    }

    private fun write(name: String, json: JSONObject) = writeBytes(name, json.toString(1).toByteArray(Charsets.UTF_8))

    private fun writeBytes(name: String, bytes: ByteArray) {
        try {
            dir?.let { File(it, name).writeBytes(bytes) }
        } catch (error: IOException) {
            // The capture is evidence: it never breaks the call.
        }
    }

    companion object {
        const val DIR = "hbperf-red"
        const val FLAG = "ACTIVA"
        private const val CHECK_MS = 1_000L
        private val COUNTER = AtomicInteger()
        private val TEXT_TYPES = listOf("json", "text", "xml", "form", "javascript", "graphql", "html")
    }
}
